package com.example.eac_backend_project.files;
import com.example.eac_backend_project.entity.inventory.User;
import com.example.eac_backend_project.repository.UserRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;
import java.io.*;
import java.nio.file.*;
import static com.example.eac_backend_project.communication.CommunicationAccess.fail;
/** Reuses managed records, versions, quotas, ACLs and audit. Does not grant access to existing documents. */
@Service @Transactional public class CommunicationFilesBridge {
 private final FileSuiteService files;private final FileItemRepository items;private final FileVersionRepository versions;private final FileOperationService operations;
 public CommunicationFilesBridge(FileSuiteService files,FileItemRepository items,FileVersionRepository versions,FileOperationService operations){this.files=files;this.items=items;this.versions=versions;this.operations=operations;}
 @org.springframework.beans.factory.annotation.Autowired private com.example.eac_backend_project.Service.PageService pages;
 private void recipient(User user){operations.require(user,"FILE_VIEW");operations.require(user,"FILE_DOWNLOAD");if(!FileSuiteService.admin(user)){var auth=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(user.getUserName(),"",List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority(user.getRole().getName())));if(pages.getAccessiblePages(auth).stream().noneMatch(p->"/files".equals(p.getPath())))throw fail(403,"A recipient needs File Management page access before receiving attachments");}}
 public Map<String,Object> describe(Long id,List<User> recipients){files.checkOperation("FILE_SHARE");var view=files.get(id);if(view.folder())throw fail(400,"Share files, not folders");FileItem item=items.findById(id).orElseThrow();
  for(User u:recipients){recipient(u);if(files.access(item,u,false)==null)throw fail(403,"A recipient cannot access "+view.name()+". Grant access explicitly in File Management before sending.");}
  return Map.of("fileId",id,"name",view.name(),"mime",view.mediaType(),"size",view.sizeBytes(),"encrypted",false);
 }
 public Long upload(byte[] encrypted,List<User> recipients)throws IOException{
  for(User user:recipients)recipient(user);
  MultipartFile part=new MultipartFile(){public String getName(){return "file";}public String getOriginalFilename(){return "Communication-"+UUID.randomUUID()+".eacsecure";}public String getContentType(){return "application/octet-stream";}public boolean isEmpty(){return encrypted.length==0;}public long getSize(){return encrypted.length;}public byte[] getBytes(){return encrypted.clone();}public InputStream getInputStream(){return new ByteArrayInputStream(encrypted);}public void transferTo(File file)throws IOException{Files.write(file.toPath(),encrypted);}};
  var view=files.upload(part,null);for(User u:recipients)if(!u.getId().equals(view.ownerId()))files.share(view.id(),u.getId(),FilePermission.Access.VIEWER,null,false);return view.id();
 }
 public byte[] download(Long id)throws IOException{return Files.readAllBytes(files.download(id,null).path());}
 public byte[] reviewDownload(Long id)throws IOException{var item=items.findById(id).orElseThrow(()->fail(404,"Managed attachment no longer exists"));if(item.getDeletedAt()!=null)throw fail(404,"Managed attachment is recycled");var version=versions.findByItem_IdAndNumber(id,item.getCurrentVersion()).orElseThrow(()->fail(404,"Managed content unavailable"));return Files.readAllBytes(new FileContentStore(root()).path(version.getStorageKey()));}
 @org.springframework.beans.factory.annotation.Autowired private FilePermissionRepository permissions;
 public List<Map<String,Object>> snapshot(Set<Long> ids)throws IOException{List<Map<String,Object>> result=new ArrayList<>();LinkedHashMap<Long,FileItem> ordered=new LinkedHashMap<>();for(Long id:ids){var node=items.findById(id).orElse(null);List<FileItem> chain=new ArrayList<>();Set<Long> seen=new HashSet<>();while(node!=null){if(!seen.add(node.getId())||seen.size()>1000)throw fail(409,"Invalid managed folder ancestry");chain.add(node);node=node.getParent();}Collections.reverse(chain);for(var entry:chain)ordered.put(entry.getId(),entry);}long total=0;for(var item:ordered.values()){Long id=item.getId();List<Map<String,Object>> content=new ArrayList<>();for(var v:versions.findByItem_IdOrderByNumberDesc(id)){byte[] bytes=Files.readAllBytes(new FileContentStore(root()).path(v.getStorageKey()));total+=bytes.length;if(total>100*1024*1024)throw fail(413,"Communication backup attachments exceed 100 MB; use infrastructure backup for larger datasets");content.add(Map.of("number",v.getNumber(),"key",v.getStorageKey(),"checksum",v.getChecksum(),"size",v.getSizeBytes(),"mime",v.getMediaType(),"editorId",v.getEditor().getId(),"createdAt",v.getCreatedAt().toString(),"bytes",Base64.getEncoder().encodeToString(bytes)));}Map<String,Object> metadata=new LinkedHashMap<>();metadata.put("id",id);metadata.put("ownerId",item.getOwner().getId());metadata.put("parentId",item.getParent()==null?null:item.getParent().getId());metadata.put("folder",item.isFolder());metadata.put("name",item.getName());metadata.put("mime",item.getMediaType());metadata.put("size",item.getSizeBytes());metadata.put("version",item.getCurrentVersion());metadata.put("createdAt",item.getCreatedAt().toString());metadata.put("updatedAt",item.getUpdatedAt().toString());metadata.put("versions",content);List<Map<String,Object>> grants=new ArrayList<>();for(var permission:permissions.findByItem_Id(id)){Map<String,Object> grant=new LinkedHashMap<>();grant.put("userId",permission.getRecipient().getId());grant.put("access",permission.getAccess().name());grant.put("downloadBlocked",permission.isDownloadBlocked());grant.put("grantedAt",permission.getGrantedAt().toString());grant.put("expiresAt",permission.getExpiresAt()==null?null:permission.getExpiresAt().toString());grants.add(grant);}metadata.put("grants",grants);result.add(metadata);}return result;}
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.jdbc.core.JdbcTemplate jdbc;
 public void restoreSnapshot(com.fasterxml.jackson.databind.JsonNode records)throws IOException{for(var item:records){Long id=item.path("id").asLong();boolean newlyRestored=!items.existsById(id);if(newlyRestored){Integer owner=jdbc.queryForObject("select count(*) from users where id=?",Integer.class,item.path("ownerId").asLong());if(owner==null||owner==0)continue;jdbc.update("insert into file_items (id,name,folder,media_type,size_bytes,current_version,created_at,updated_at,owner_id,revision,collaboration_epoch,parent_id) values (?,?,?,?,?,?,?,?,?,?,?,?)",id,item.path("name").asText(),item.path("folder").asBoolean(),item.path("mime").asText(),item.path("size").asLong(),item.path("version").asLong(),java.sql.Timestamp.from(java.time.Instant.parse(item.path("createdAt").asText())),java.sql.Timestamp.from(java.time.Instant.parse(item.path("updatedAt").asText())),item.path("ownerId").asLong(),0,UUID.randomUUID().toString(),item.path("parentId").isNull()||item.path("parentId").isMissingNode()?null:item.path("parentId").asLong());}
 if(newlyRestored)for(var grant:item.path("grants")){Integer exists=jdbc.queryForObject("select count(*) from users where id=?",Integer.class,grant.path("userId").asLong());if(exists!=null&&exists>0)jdbc.update("insert into file_permissions (item_id,recipient_id,access,granted_at,expires_at,download_blocked) values (?,?,?,?,?,?)",id,grant.path("userId").asLong(),FilePermission.Access.valueOf(grant.path("access").asText()).name(),java.sql.Timestamp.from(java.time.Instant.parse(grant.path("grantedAt").asText())),grant.path("expiresAt").isNull()?null:java.sql.Timestamp.from(java.time.Instant.parse(grant.path("expiresAt").asText())),grant.path("downloadBlocked").asBoolean(false)); }
 for(var v:item.path("versions")){String key=v.path("key").asText();Path path=new FileContentStore(root()).path(key);byte[] bytes=Base64.getDecoder().decode(v.path("bytes").asText());String hash;try{hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception ex){throw new IOException("Checksum unavailable");}if(!hash.equals(v.path("checksum").asText()))throw fail(400,"Attachment backup checksum mismatch");if(!Files.exists(path)){Files.createDirectories(path.getParent());Files.write(path,bytes,StandardOpenOption.CREATE_NEW);org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCompletion(int status){if(status!=STATUS_COMMITTED)try{Files.deleteIfExists(path);}catch(IOException ignored){}}});}
 if(versions.findByItem_IdAndNumber(id,v.path("number").asLong()).isEmpty())jdbc.update("insert into file_versions (item_id,version_number,storage_key,checksum,size_bytes,media_type,editor_id,created_at,reason) values (?,?,?,?,?,?,?,?,?)",id,v.path("number").asLong(),key,hash,bytes.length,v.path("mime").asText(),v.path("editorId").asLong(),java.sql.Timestamp.from(java.time.Instant.parse(v.path("createdAt").asText())),"Communication backup recovery");}
 }}
 private String root(){return contentStoreRoot;}
 @org.springframework.beans.factory.annotation.Value("${app.files.storage-root:./uploads/file-suite}")private String contentStoreRoot;
}
